{
  "criteria": [
    {
      "kind": "exclusion",
      "text": "Positive patch test reaction to one or more allergens (score 1+ or above) in baseline or extended series or personal products, deemed clinically relevant as current cause of hand and foot dermatitis.",
      "quote": "Patients with a positive patch test reaction to one or more allergens (a score of 1+ or above according to International Contact Dermatitis Research Group [ICDRG] grading scale)",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Documented diagnosis of protein contact dermatitis of hands and/or feet, with positive prick test and lesions of contact urticaria or dermatitis.",
      "quote": "Patients with a documented diagnosis of protein contact dermatitis of hands and/or feet.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients in whom patch testing cannot be conducted due to any reason (e.g., refusal, inability to washout, lack of clear skin).",
      "quote": "Patients in whom patch testing cannot be conducted due to any reason",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Documented exposure to irritants in occupational or non-occupational setting that is believed to be a predominant cause of current hand and foot dermatitis.",
      "quote": "Patients with documented exposure to irritants in the occupational or non-occupational (household/recreational) setting that is believed to be a predominant cause of the current hand and foot dermatitis",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Age at or above 10 years.",
      "quote": "Age at or above 10 years.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Use of systemic corticosteroids, immunosuppressive/immunomodulating drugs, or phototherapy within 4 weeks before baseline visit.",
      "quote": "Patients who have used any the following treatments within 4 weeks before the baseline visit",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Treatment with cell-depleting agents (e.g., rituximab) within 6 months or until lymphocyte count normal, or other biologics within 5 half-lives or 16 weeks.",
      "quote": "Treatment with biologics, other than dupilumab, as follows:",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Treatment with TCS, TCI, crisaborole, or topical JAK inhibitor within 2 weeks before baseline on hands and feet.",
      "quote": "Treatment with TCS or TCI or crisaborole or topical Janus kinase (JAK) inhibitor within 2 weeks before the baseline visit on the hand and foot.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Treatment with an investigational drug within 8 weeks or 5 half-lives before baseline.",
      "quote": "Treatment with an investigational drug within 8 weeks or within 5 half-lives (if known), whichever is longer, before the baseline visit.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Treatment with a live (attenuated) vaccine within 4 weeks before baseline.",
      "quote": "Treatment with a live (attenuated) vaccine within 4 weeks before the baseline visit.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Planned or anticipated use of any prohibited medications and procedures during study treatment.",
      "quote": "Planned or anticipated use of any prohibited medications and procedures during study treatment.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Known or suspected immunodeficiency, including history of invasive opportunistic infections or recurrent infections of abnormal frequency.",
      "quote": "Known or suspected immunodeficiency, including history of invasive opportunistic infections",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Known history of HIV infection or HIV seropositivity.",
      "quote": "Known history of human immunodeficiency virus (HIV) infection or HIV seropositivity.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Current diagnosis of hepatitis B viral infection as evidenced by positive HBsAg or positive HBcAb confirmed by positive HBV DNA.",
      "quote": "With a current diagnosis of hepatitis B viral infection at the time of screening",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Current diagnosis of hepatitis C viral infection as evidenced by positive HCV Ab and positive HCV RNA.",
      "quote": "With a current diagnosis of hepatitis C viral infection at the time of screening",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "On current treatment for hepatic disease or evidence of liver disease with persistent elevated transaminases >3x ULN during screening.",
      "quote": "On current treatment for hepatic disease including but not limited to acute or chronic hepatitis, cirrhosis, or hepatic failure, or has evidence of liver disease as indicated by persistent (confirmed by repeated tests ≥2 weeks apart) elevated transaminases",
      "thresholds": [
        {"test": "ALT", "op": ">", "value": 3, "unit": "x ULN"},
        {"test": "AST", "op": ">", "value": 3, "unit": "x ULN"}
      ]
    },
    {
      "kind": "exclusion",
      "text": "Presence of any of the following laboratory abnormalities at screening: platelets ≤100 × 10^3/μL or neutrophils <1.5 × 10^3/μL.",
      "quote": "Presence of any 1 or more of the following abnormalities in laboratory test results at screening:",
      "thresholds": [
        {"test": "Platelets", "op": "<=", "value": 100, "unit": "10^3/μL"},
        {"test": "Neutrophils", "op": "<", "value": 1.5, "unit": "10^3/μL"}
      ]
    },
    {
      "kind": "exclusion",
      "text": "Diagnosed active endoparasitic infections, or suspected/high risk unless ruled out before randomization.",
      "quote": "Diagnosed active endoparasitic infections.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Presence of skin comorbidities on hand and foot that may interfere with study assessments (e.g., palmoplantar psoriasis, keratoderma, lichen planus, etc.).",
      "quote": "Presence of skin comorbidities on hand and foot that may interfere with study assessments.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of malignancy within 5 years before baseline, except completely treated in situ carcinoma of cervix or non-metastatic squamous/basal cell carcinoma of skin.",
      "quote": "History of malignancy within 5 years before the baseline visit, except completely treated in situ carcinoma of the cervix, completely treated and resolved non-metastatic squamous or basal cell carcinoma of the skin.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Severe concomitant illness(es) that would adversely affect participation, e.g., short life expectancy, uncontrolled diabetes (HbA1c ≥9%), cardiovascular conditions, etc.",
      "quote": "Severe concomitant illness(es) that, in the investigator’s judgment, would adversely affect the patient’s participation in the study.",
      "thresholds": [
        {"test": "HbA1c", "op": ">=", "value": 9, "unit": "%"}
      ]
    },
    {
      "kind": "exclusion",
      "text": "Any other medical or psychological condition that may suggest new disease, present unreasonable risk, make participation unreliable, or interfere with assessments.",
      "quote": "Any other medical or psychological condition (including relevant laboratory abnormalities at screening) that, in the opinion of the investigator, may suggest a new and/or insufficiently understood disease",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of alcohol or drug abuse within 2 years before screening visit.",
      "quote": "History of alcohol or drug abuse within 2 years before the screening visit.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients committed to an institution by judicial or administrative order.",
      "quote": "Patients who are committed to an institution by virtue of an order issued either by the judicial or the administrative authorities.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patient is a member of the investigational team or his/her immediate family.",
      "quote": "Patient is a member of the investigational team or his/her immediate family.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Pregnant or breastfeeding women or planning to become pregnant or breastfeed during participation.",
      "quote": "Pregnant or breastfeeding women or planning to become pregnant or breastfeed during the patient’s participation in this study.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Women of childbearing potential unwilling to practice highly effective contraception during study and for at least 12 weeks after last dose.",
      "quote": "Women of childbearing potential (WOCBP)* who are unwilling to practice highly effective contraception prior to the initial dose/start of the first treatment, during the study, and for at least 12 weeks after the last dose.",
      "thresholds": []
    }
  ]
}
